SELECT COUNT(*) FROM MARATHON_CONTEST A, MARATHON_CONTEST_TYPE B WHERE A.contest_idx = B.contest_idx AND A.homepage_id = #{homepage_id} AND B.homepage_id = #{homepage_id} AND A.del_yn = 'N' AND B.del_yn = 'N'
AND B.contest_idx = #{contest_idx}
AND A.${search_type} LIKE '%${search_text}%'

${pagingTop} SELECT B.homepage_id, B.contest_idx, A.contest_name, B.contest_type_idx, B.contest_type, B.page_count, B.application_subject, B.add_date, B.add_id, B.modify_date, B.modify_id FROM MARATHON_CONTEST A, MARATHON_CONTEST_TYPE B WHERE A.contest_idx = B.contest_idx AND A.homepage_id = #{homepage_id} AND B.homepage_id = #{homepage_id} AND A.del_yn = 'N' AND B.del_yn = 'N'
AND B.contest_idx = #{contest_idx}
AND A.${search_type} LIKE '%${search_text}%'
ORDER BY contest_idx DESC, contest_type_idx ${pagingBottom}

SELECT
	B.homepage_id, B.contest_idx, A.contest_name, B.contest_type_idx, B.contest_type,
	B.page_count, B.application_subject, B.add_date, B.add_id, B.modify_date,
	B.modify_id
FROM
	MARATHON_CONTEST A, MARATHON_CONTEST_TYPE B
WHERE
	A.contest_idx = B.contest_idx
AND	A.homepage_id = #{homepage_id}
AND	B.homepage_id = #{homepage_id}
AND	B.contest_idx = #{contest_idx}
AND	B.contest_type_idx = #{contest_type_idx}

mapper.insert:

	SELECT NVL(MAX(contest_type_idx), 0) + 1 FROM MARATHON_CONTEST_TYPE WHERE homepage_id = #{homepage_id} AND contest_idx = #{contest_idx}

INSERT INTO
	MARATHON_CONTEST_TYPE
(
	homepage_id, contest_idx, contest_type_idx, contest_type, page_count,
	application_subject, add_date, add_id, modify_date, modify_id
)
	VALUES
(
	#{homepage_id}, #{contest_idx}, #{contest_type_idx}, #{contest_type}, #{page_count},
	#{application_subject}, SYSDATE, #{add_id}, #{modify_date}, #{modify_id}
)

mapper.update:
UPDATE
	MARATHON_CONTEST_TYPE
SET
	contest_idx = #{contest_idx},
	contest_type = #{contest_type},
	page_count = #{page_count},
	application_subject = #{application_subject},
	modify_date = SYSDATE,
	modify_id = #{modify_id}
WHERE
	homepage_id = #{homepage_id}
AND	contest_idx = #{contest_idx}
AND	contest_type_idx = #{contest_type_idx}

UPDATE
	MARATHON_CONTEST_TYPE
SET
	del_yn = 'Y'
WHERE
	homepage_id = #{homepage_id}
AND	contest_idx = #{contest_idx}
AND	contest_type_idx = #{contest_type_idx}
